"use client";

import { useCallback } from "react";
import {
  requestStudioManualImageGenerate,
  requestStudioPreparePlan,
  requestStudioPrepareResolve,
  requestStudioSfxPlan,
  type ApiErrorResponse,
  type StudioManualImageGenerateResponse,
} from "@/lib/api/studio-client";
import { fetchStudioSfxCatalog } from "@/lib/api/studio-client";
import { GENERAL_STUDIO_SFX_CATEGORY_ID, resolveAutoSfxCategoryIds } from "@/lib/studio/audio-options";
import type { StudioProjectProfileSnapshot } from "@/lib/studio/project-profile-snapshot";
import type { StudioSfxAutoLevel } from "@/lib/studio/sfx-auto-tuning";
import { trackWorkflowEvent } from "@/lib/telemetry/client";
import type { PublishCategory } from "@/lib/publish/types";
import {
  isStudioAutoGeneratedImageSource,
  isStudioGeneratedImageSource,
  type CrawlMode,
  type ImageSource,
  type PreparedSlide,
  type StoryCharacterProfile,
} from "@/types/studio-json";
import type { Dispatch, SetStateAction } from "react";

type PreviewTimingState = {
  slides: PreparedSlide[];
  frameDurationsSec: number[];
};

type RenderUsageState = {
  ttsChars: number;
  renderSeconds: number;
};

type HandlePrepareOptions = {
  preparePayloadOverride?: Record<string, unknown>;
  throwOnError?: boolean;
};

type StudioPrepareImageMode = "crawl-only" | "manual-ai-prompt" | "auto-ai-generate";

type AutoGeneratedPreparedSlidesResult = {
  slides: PreparedSlide[];
  characterProfiles?: StoryCharacterProfile[];
  warnings: string[];
  successCount: number;
  failureCount: number;
};

function clearSfxDecisionForSlide(slides: PreparedSlide[], targetSlideIndex: number): PreparedSlide[] {
  if (!Number.isInteger(targetSlideIndex) || targetSlideIndex < 0 || targetSlideIndex >= slides.length) {
    return slides;
  }
  return slides.map((slide, slideIndex) =>
    slideIndex === targetSlideIndex
      ? {
          ...slide,
          sfxPlan: undefined,
          sfxCue: undefined,
        }
      : slide
  );
}

function shouldMarkFullSfxPlanCompleted(targetSlideIndex: number | null): boolean {
  return targetSlideIndex === null;
}

function mergeCharacterProfilesIntoPayload(
  source: Record<string, unknown>,
  characterProfiles?: StoryCharacterProfile[]
): Record<string, unknown> {
  if (!Array.isArray(characterProfiles) || characterProfiles.length <= 0) return source;
  return {
    ...source,
    characterProfiles,
  };
}

function resolveStudioPrepareImageMode(imageSource: ImageSource): StudioPrepareImageMode {
  if (isStudioAutoGeneratedImageSource(imageSource)) return "auto-ai-generate";
  if (isStudioGeneratedImageSource(imageSource)) return "manual-ai-prompt";
  return "crawl-only";
}

function toVisibleStudioWarnings(warnings: string[]): string[] {
  return Array.from(
    new Set(
      warnings
        .map((warning) => String(warning || "").trim())
        .filter((warning) => warning && !warning.startsWith("[timing]"))
    )
  );
}

async function autoGeneratePreparedSlides(input: {
  enabled: boolean;
  publishCategory: PublishCategory;
  slides: PreparedSlide[];
  codexModel?: string;
  imageStylePrompt?: string;
  characterProfiles?: StoryCharacterProfile[];
  fixedCharacterProfileId?: string;
  requestManualImageGenerate?: (input: {
    publishCategory: PublishCategory;
    imageSource: "auto-ai-generate";
    slides: PreparedSlide[];
    slideIndexes?: number[];
    mode: "selected" | "missing" | "all";
    codexModel?: string;
    imageStylePrompt?: string;
    characterProfiles?: StoryCharacterProfile[];
    fixedCharacterProfileId?: string;
    projectProfileSnapshot?: StudioProjectProfileSnapshot | null;
  }) => Promise<StudioManualImageGenerateResponse>;
  projectProfileSnapshot?: StudioProjectProfileSnapshot | null;
}): Promise<AutoGeneratedPreparedSlidesResult> {
  if (!input.enabled) {
    return {
      slides: input.slides,
      characterProfiles: input.characterProfiles,
      warnings: [],
      successCount: 0,
      failureCount: 0,
    };
  }
  const fixedCharacterProfileId = String(input.fixedCharacterProfileId || "").trim();
  const imageState = fixedCharacterProfileId
    ? { fixedCharacterProfileId }
    : {
        imageStylePrompt: input.imageStylePrompt,
        characterProfiles: input.characterProfiles,
      };
  const response = await (input.requestManualImageGenerate || requestStudioManualImageGenerate)({
    publishCategory: input.publishCategory,
    imageSource: "auto-ai-generate",
    slides: input.slides,
    mode: "missing",
    codexModel: input.codexModel,
    ...imageState,
    projectProfileSnapshot: input.projectProfileSnapshot,
  });
  const successCount = response.results.filter((item) => item.status === "ok").length;
  const failureCount = response.results.filter((item) => item.status === "error").length;
  return {
    slides: response.slides,
    characterProfiles: response.characterProfiles,
    warnings: toVisibleStudioWarnings(Array.isArray(response.warnings) ? response.warnings : []),
    successCount,
    failureCount,
  };
}

export function useStudioPrepareFlow(input: {
  parsed: unknown;
  publishCategory: PublishCategory;
  codexModel: string;
  imageSource: ImageSource;
  crawlMode: CrawlMode;
  debugImageSearch: boolean;
  projectProfileSnapshot?: StudioProjectProfileSnapshot | null;
  fixedCharacterProfileId?: string;
  sfxCategoryIds: string[];
  sfxAutoLevel: StudioSfxAutoLevel;
  setBusyAction: Dispatch<SetStateAction<boolean>>;
  setSlidesAction: Dispatch<SetStateAction<PreparedSlide[]>>;
  setPreviewTimingAction: Dispatch<SetStateAction<PreviewTimingState | null>>;
  setImageErrorsAction: Dispatch<SetStateAction<string[]>>;
  setRenderUsageAction: Dispatch<SetStateAction<RenderUsageState | null>>;
  setRenderStatusAction: Dispatch<SetStateAction<string>>;
  getCurrentSlidesAction: () => PreparedSlide[];
  getPreparePayloadAction?: () => Record<string, unknown> | null;
  getPreparedPayloadAction: () => Record<string, unknown> | null;
  setJsonTextAction?: Dispatch<SetStateAction<string>>;
  buildPreparedPayloadFromSlidesAction: (slides: PreparedSlide[]) => Record<string, unknown> | null;
  shouldAutoPlanSfxAfterPrepareAction: () => boolean;
  markSfxPlanCompletedAction: () => void;
  nowMsAction: () => number;
  toTimingDetailAction: (label: string, ms: number, extra?: string) => string;
  toEventDetailFromApiErrorAction: (data: ApiErrorResponse, fallback: string) => string;
  transformPreparedSlidesAction?: (slides: PreparedSlide[]) => PreparedSlide[];
}) {
  const clearAutoSfxFromSlides = useCallback(
    (slidesToApply: PreparedSlide[]) =>
      slidesToApply.map((slide) => {
        const hasAutoCue = slide.sfxCue?.source === "auto";
        if (!slide.sfxPlan && !hasAutoCue) return slide;
        return {
          ...slide,
          sfxPlan: undefined,
          sfxCue: hasAutoCue ? undefined : slide.sfxCue,
        };
      }),
    []
  );

  const resolveRequestedSfxCategories = useCallback(async (): Promise<string[]> => {
    const configured = Array.from(new Set(input.sfxCategoryIds.map((tag) => String(tag || "").trim()).filter(Boolean))).slice(0, 24);
    if (configured.length > 0) return configured;
    try {
      const data = await fetchStudioSfxCatalog();
      const categories = Array.isArray(data.categories) ? data.categories : [];
      return resolveAutoSfxCategoryIds(categories, GENERAL_STUDIO_SFX_CATEGORY_ID);
    } catch {
      return [];
    }
  }, [input.sfxCategoryIds]);

  const applySfxPlanToSlides = useCallback(
    async (slidesToApply: PreparedSlide[], options?: { bestEffort?: boolean; targetSlideIndex?: number }) => {
      const targetSlideIndex = Number.isInteger(options?.targetSlideIndex)
        ? Number(options?.targetSlideIndex)
        : null;
      const replannableSlides =
        targetSlideIndex === null
          ? clearAutoSfxFromSlides(slidesToApply)
          : clearSfxDecisionForSlide(slidesToApply, targetSlideIndex);
      const payload = input.buildPreparedPayloadFromSlidesAction(replannableSlides);
      if (!payload) return { slides: slidesToApply, warnings: [] as string[] };
      const requestedSfxCategories = await resolveRequestedSfxCategories();
      const { responseOk, data } = await requestStudioSfxPlan({
        parsed: payload,
        publishCategory: input.publishCategory,
        codexModel: input.codexModel,
        sfxCategories: requestedSfxCategories,
        bestEffortSfxPlan: options?.bestEffort,
        targetSlideIndexes: targetSlideIndex === null ? undefined : [targetSlideIndex],
      });
      if (!responseOk || !("ok" in data) || !data.ok) {
        throw new Error("error" in data ? data.error : "자동 SFX 배정에 실패했습니다.");
      }
      const nextSlides = replannableSlides.map((slide, index) => {
        if (targetSlideIndex !== null && index !== targetSlideIndex) return slidesToApply[index] || slide;
        const nextPlan = data.slides[index]?.sfxPlan;
        const currentStepIndex = Number.isFinite(slide.stepIndex) ? Number(slide.stepIndex) : 0;
        const matchedPlanCue =
          Array.isArray(nextPlan) && nextPlan.length > 0
            ? nextPlan.find(
                (item) =>
                  Number.isFinite(item?.lineIndex) &&
                  Math.floor(Number(item.lineIndex)) === currentStepIndex &&
                  String(item?.tag || "").trim()
              )
            : null;
        return {
          ...slide,
          sfxPlan: nextPlan,
          sfxCue: matchedPlanCue
            ? {
                enabled: true,
                tag: String(matchedPlanCue.tag || "").trim(),
                gainDb: typeof matchedPlanCue.gainDb === "number" ? matchedPlanCue.gainDb : undefined,
                offsetMs: typeof matchedPlanCue.offsetMs === "number" ? matchedPlanCue.offsetMs : undefined,
                source: "auto" as const,
              }
            : data.slides[index]?.sfxCue ?? slide.sfxCue,
        };
      });
      if (shouldMarkFullSfxPlanCompleted(targetSlideIndex)) {
        input.markSfxPlanCompletedAction();
      }
      return {
        slides: nextSlides,
        warnings: Array.isArray(data.warnings) ? data.warnings : [],
      };
    },
    [clearAutoSfxFromSlides, input, resolveRequestedSfxCategories]
  );

  const handlePrepare = useCallback(async (options?: HandlePrepareOptions): Promise<PreparedSlide[] | null> => {
    input.setBusyAction(true);
    try {
      const imageMode = resolveStudioPrepareImageMode(input.imageSource);
      const isPromptImageMode = imageMode !== "crawl-only";
      const shouldAutoGenerateImages = imageMode === "auto-ai-generate";
      const shouldAutoPlanSfx = input.shouldAutoPlanSfxAfterPrepareAction();
      const baseTotalSteps = shouldAutoGenerateImages ? 5 : 4;
      const totalSteps = shouldAutoPlanSfx ? baseTotalSteps + 1 : baseTotalSteps;
      input.setRenderStatusAction(`1/${totalSteps} 미리보기 요청 준비 중`);
      const preparePayload =
        options?.preparePayloadOverride ||
        (input.getPreparePayloadAction ? input.getPreparePayloadAction() : input.parsed as Record<string, unknown> | null);
      if (!preparePayload || typeof preparePayload !== "object") {
        throw new Error("유효하지 않은 JSON입니다.");
      }
      const payloadSlides = (preparePayload as Record<string, unknown>).slides;
      const slideCount = Array.isArray(payloadSlides) ? payloadSlides.length : 0;
      console.info(`[studio-prepare] payload_ready slides=${slideCount} category=${input.publishCategory}`);
      input.setRenderStatusAction(
        isPromptImageMode
          ? `2/${totalSteps} 슬라이드별 AI 이미지 프롬프트 준비 중`
          : `2/${totalSteps} 미리보기용 Codex 이미지 후보 찾는 중`
      );
      trackWorkflowEvent({
        name: "prepare_clicked",
        page: "studio",
        stage: "prepare",
        status: "success",
      });
      const prepareStartedAt = input.nowMsAction();
      const planStartedAt = input.nowMsAction();
      const { responseOk: planResponseOk, data: planData } = await requestStudioPreparePlan({
        parsed: preparePayload,
        publishCategory: input.publishCategory,
        codexModel: input.codexModel,
        projectProfileSnapshot: input.projectProfileSnapshot,
        fixedCharacterProfileId: input.fixedCharacterProfileId,
        imageSource: input.imageSource,
        crawlMode: input.crawlMode,
        debugImageSearch: input.debugImageSearch,
      });
      if (!planResponseOk || !("ok" in planData) || !planData.ok) {
        const reason = "error" in planData ? planData.error : "Codex 이미지 후보 계획에 실패했습니다.";
        const detail = "error" in planData ? input.toEventDetailFromApiErrorAction(planData, reason) : reason;
        trackWorkflowEvent({
          name: "prepare_failed",
          page: "studio",
          stage: "prepare",
          status: "failure",
          detail: `${detail}, ${input.toTimingDetailAction("prepare_plan_api", input.nowMsAction() - planStartedAt)}`,
          errorCode: "errorCode" in planData ? planData.errorCode : undefined,
          retryable: "retryable" in planData ? planData.retryable : undefined,
        });
        trackWorkflowEvent({
          name: "stage_timing",
          page: "studio",
          stage: "prepare_plan_api",
          status: "failure",
          detail: input.toTimingDetailAction("prepare_plan_api", input.nowMsAction() - planStartedAt),
        });
        throw new Error(reason);
      }
      trackWorkflowEvent({
        name: "stage_timing",
        page: "studio",
        stage: "prepare_plan_api",
        status: "success",
        detail: input.toTimingDetailAction("prepare_plan_api", input.nowMsAction() - planStartedAt),
      });
      input.setRenderStatusAction(
        isPromptImageMode
          ? `3/${totalSteps} 프롬프트 기반 미리보기 반영 중`
          : `3/${totalSteps} 실제 이미지 크롤링/선택 중`
      );
      const resolveStartedAt = input.nowMsAction();
      const { responseOk: resolveResponseOk, data: resolveData } = await requestStudioPrepareResolve({
        parsed: {
          ...preparePayload,
          slides: planData.slides,
        },
        publishCategory: input.publishCategory,
        codexModel: input.codexModel,
        projectProfileSnapshot: input.projectProfileSnapshot,
        fixedCharacterProfileId: input.fixedCharacterProfileId,
        imageSource: input.imageSource,
        crawlMode: input.crawlMode,
        debugImageSearch: input.debugImageSearch,
      });
      if (!resolveResponseOk || !("ok" in resolveData) || !resolveData.ok) {
        const reason = "error" in resolveData ? resolveData.error : "이미지 크롤링과 선택에 실패했습니다.";
        const detail = "error" in resolveData ? input.toEventDetailFromApiErrorAction(resolveData, reason) : reason;
        trackWorkflowEvent({
          name: "prepare_failed",
          page: "studio",
          stage: "prepare",
          status: "failure",
          detail: `${detail}, ${input.toTimingDetailAction("prepare_resolve_api", input.nowMsAction() - resolveStartedAt)}`,
          errorCode: "errorCode" in resolveData ? resolveData.errorCode : undefined,
          retryable: "retryable" in resolveData ? resolveData.retryable : undefined,
        });
        trackWorkflowEvent({
          name: "stage_timing",
          page: "studio",
          stage: "prepare_resolve_api",
          status: "failure",
          detail: input.toTimingDetailAction("prepare_resolve_api", input.nowMsAction() - resolveStartedAt),
        });
        throw new Error(reason);
      }
      trackWorkflowEvent({
        name: "stage_timing",
        page: "studio",
        stage: "prepare_resolve_api",
        status: "success",
        detail: input.toTimingDetailAction(
          "prepare_resolve_api",
          input.nowMsAction() - resolveStartedAt,
          resolveData.usage?.imagePolicyMs ? `server_ms=${Math.round(resolveData.usage.imagePolicyMs)}` : ""
        ),
      });
      let nextSlides = resolveData.slides;
      let nextWarnings = toVisibleStudioWarnings([
        ...(Array.isArray(planData.warnings) ? planData.warnings : []),
        ...(Array.isArray(resolveData.warnings) ? resolveData.warnings : []),
      ]);
      let autoGeneratedFailureCount = 0;
      if (shouldAutoGenerateImages) {
        input.setRenderStatusAction(`4/${totalSteps} 이미지 없는 슬라이드 Codex 생성 중`);
        const autoGenerateStartedAt = input.nowMsAction();
        try {
          const autoGenerated = await autoGeneratePreparedSlides({
            enabled: true,
            publishCategory: input.publishCategory,
            slides: nextSlides,
            codexModel: input.codexModel,
            imageStylePrompt: String((preparePayload as Record<string, unknown>).imageStylePrompt || "").trim() || undefined,
            characterProfiles: Array.isArray((preparePayload as Record<string, unknown>).characterProfiles)
              ? ((preparePayload as Record<string, unknown>).characterProfiles as StoryCharacterProfile[])
              : undefined,
            fixedCharacterProfileId: input.fixedCharacterProfileId,
            projectProfileSnapshot: input.projectProfileSnapshot,
          });
          nextSlides = autoGenerated.slides;
          if (autoGenerated.characterProfiles?.length && input.setJsonTextAction) {
            input.setJsonTextAction((current) => {
              try {
                const parsedCurrent = JSON.parse(current) as Record<string, unknown>;
                if (!parsedCurrent || typeof parsedCurrent !== "object" || Array.isArray(parsedCurrent)) return current;
                return JSON.stringify(mergeCharacterProfilesIntoPayload(parsedCurrent, autoGenerated.characterProfiles), null, 2);
              } catch {
                return current;
              }
            });
          }
          nextWarnings = toVisibleStudioWarnings([...nextWarnings, ...autoGenerated.warnings]);
          autoGeneratedFailureCount = autoGenerated.failureCount;
          trackWorkflowEvent({
            name: "stage_timing",
            page: "studio",
            stage: "manual_image_generate_api",
            status: "success",
            detail: input.toTimingDetailAction(
              "manual_image_generate_api",
              input.nowMsAction() - autoGenerateStartedAt,
              `successes=${autoGenerated.successCount}, failures=${autoGenerated.failureCount}`
            ),
          });
        } catch (error) {
          trackWorkflowEvent({
            name: "stage_timing",
            page: "studio",
            stage: "manual_image_generate_api",
            status: "failure",
            detail: input.toTimingDetailAction("manual_image_generate_api", input.nowMsAction() - autoGenerateStartedAt),
          });
          throw error;
        }
      }
      const previewApplyStep = shouldAutoPlanSfx ? totalSteps - 1 : totalSteps;
      input.setRenderStatusAction(`${previewApplyStep}/${totalSteps} 미리보기 프레임 반영 중`);
      if (shouldAutoPlanSfx) {
        input.setRenderStatusAction(`${totalSteps}/${totalSteps} SFX 자동 배정 중`);
        const sfxPlanStartedAt = input.nowMsAction();
        const planned = await applySfxPlanToSlides(nextSlides, { bestEffort: true });
        nextSlides = planned.slides;
        nextWarnings = toVisibleStudioWarnings([...nextWarnings, ...planned.warnings]);
        trackWorkflowEvent({
          name: "stage_timing",
          page: "studio",
          stage: "sfx_plan",
          status: "success",
          detail: input.toTimingDetailAction("sfx_plan_api", input.nowMsAction() - sfxPlanStartedAt),
        });
      }
      const finalSlides = input.transformPreparedSlidesAction ? input.transformPreparedSlidesAction(nextSlides) : nextSlides;
      input.setSlidesAction(finalSlides);
      input.setPreviewTimingAction(null);
      input.setImageErrorsAction(nextWarnings);
      input.setRenderUsageAction(null);
      input.setRenderStatusAction(
        autoGeneratedFailureCount > 0 ? `미리보기 준비 완료 (AI 이미지 ${autoGeneratedFailureCount}건 경고)` : "미리보기 준비 완료"
      );
      trackWorkflowEvent({
        name: "prepare_succeeded",
        page: "studio",
        stage: "prepare",
        status: "success",
        detail: input.toTimingDetailAction(
          "prepare_api",
          input.nowMsAction() - prepareStartedAt,
          resolveData.usage?.imagePolicyMs ? `server_ms=${Math.round(resolveData.usage.imagePolicyMs)}` : ""
        ),
      });
      trackWorkflowEvent({
        name: "stage_timing",
        page: "studio",
        stage: "prepare_api",
        status: "success",
        detail: input.toTimingDetailAction(
          "prepare_api",
          input.nowMsAction() - prepareStartedAt,
          resolveData.usage?.imagePolicyMs ? `server_ms=${Math.round(resolveData.usage.imagePolicyMs)}` : ""
        ),
      });
      trackWorkflowEvent({
        name: "preview_built",
        page: "studio",
        stage: "prepare",
        status: "success",
      });
      return finalSlides;
    } catch (error) {
      const resolvedError = error instanceof Error ? error : new Error(String(error));
      input.setRenderStatusAction(`미리보기 준비 실패: ${resolvedError.message}`);
      trackWorkflowEvent({
        name: "preview_built",
        page: "studio",
        stage: "prepare",
        status: "failure",
        detail: resolvedError.message,
      });
      if (options?.throwOnError) throw resolvedError;
      alert(resolvedError.message);
      return null;
    } finally {
      input.setBusyAction(false);
    }
  }, [input]);

  const handleAutoPlanSfx = useCallback(async () => {
    const payload = input.getPreparedPayloadAction();
    if (!payload) {
      alert("먼저 미리보기를 만들어 주세요.");
      return;
    }
    input.setBusyAction(true);
    input.setRenderStatusAction("SFX 자동 배정 중");
    const startedAt = input.nowMsAction();
    try {
      const currentSlides = input.getCurrentSlidesAction();
      if (!Array.isArray(currentSlides) || currentSlides.length <= 0) {
        throw new Error("먼저 미리보기를 만들어 주세요.");
      }
      const planned = await applySfxPlanToSlides(currentSlides);
      input.setSlidesAction(input.transformPreparedSlidesAction ? input.transformPreparedSlidesAction(planned.slides) : planned.slides);
      input.setImageErrorsAction((currentWarnings) => [...currentWarnings, ...planned.warnings]);
      input.setRenderStatusAction("SFX 자동 배정 완료");
      trackWorkflowEvent({
        name: "stage_timing",
        page: "studio",
        stage: "sfx_plan",
        status: "success",
        detail: input.toTimingDetailAction("sfx_plan_api", input.nowMsAction() - startedAt),
      });
    } catch (error) {
      const resolvedError = error instanceof Error ? error : new Error(String(error));
      input.setRenderStatusAction(`SFX 자동 배정 실패: ${resolvedError.message}`);
      trackWorkflowEvent({
        name: "stage_timing",
        page: "studio",
        stage: "sfx_plan",
        status: "failure",
        detail: resolvedError.message,
      });
      alert(resolvedError.message);
    } finally {
      input.setBusyAction(false);
    }
  }, [applySfxPlanToSlides, input]);

  const handleAutoPlanSfxForSlide = useCallback(
    async (targetSlideIndex: number) => {
      const currentSlides = input.getCurrentSlidesAction();
      if (
        !Array.isArray(currentSlides) ||
        !Number.isInteger(targetSlideIndex) ||
        targetSlideIndex < 0 ||
        targetSlideIndex >= currentSlides.length
      ) {
        alert("다시 추천할 효과음 항목을 찾지 못했습니다.");
        return;
      }
      input.setBusyAction(true);
      input.setRenderStatusAction(`슬라이드 ${targetSlideIndex + 1} 효과음 다시 추천 중`);
      const startedAt = input.nowMsAction();
      try {
        const planned = await applySfxPlanToSlides(currentSlides, { targetSlideIndex });
        input.setSlidesAction(planned.slides);
        input.setImageErrorsAction((currentWarnings) =>
          toVisibleStudioWarnings([...currentWarnings, ...planned.warnings])
        );
        input.setRenderStatusAction(`슬라이드 ${targetSlideIndex + 1} 효과음 다시 추천 완료`);
        trackWorkflowEvent({
          name: "stage_timing",
          page: "studio",
          stage: "sfx_plan_slide",
          status: "success",
          detail: input.toTimingDetailAction("sfx_plan_slide_api", input.nowMsAction() - startedAt),
        });
      } catch (error) {
        const resolvedError = error instanceof Error ? error : new Error(String(error));
        input.setRenderStatusAction(`효과음 다시 추천 실패: ${resolvedError.message}`);
        trackWorkflowEvent({
          name: "stage_timing",
          page: "studio",
          stage: "sfx_plan_slide",
          status: "failure",
          detail: resolvedError.message,
        });
        alert(resolvedError.message);
      } finally {
        input.setBusyAction(false);
      }
    },
    [applySfxPlanToSlides, input]
  );

  return {
    handlePrepare,
    handleAutoPlanSfx,
    handleAutoPlanSfxForSlide,
  };
}

export const __internal = {
  autoGeneratePreparedSlides,
  clearSfxDecisionForSlide,
  mergeCharacterProfilesIntoPayload,
  resolveStudioPrepareImageMode,
  shouldMarkFullSfxPlanCompleted,
  toVisibleStudioWarnings,
};
